/*
 * MapGenGeometryEdit - see inc/common/mapgen_geometry_edit.h.
 *
 * The whole schedule is built up front and never consulted about fidelity
 * while it is being built. That is deliberate: the moment the plan knows what
 * F it is for, a lower F stops being a superset of a higher one and the
 * control stops meaning anything.
 */

#include "common/mapgen_geometry_edit.h"
#include "common/mapgen_graft.h"
#include "mapgen_flood_rules.h"

#include "common/mapgen_bundle.h"
#include "common/mapgen_closure.h"
#include "common/mapgen_rooms.h"
#include "common/mapgen_trace.h"

#include <dirent.h>
#include <math.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

bool MapGenGeometryEdit_MovesArchitecture(mapgen_edit_kind_t kind)
{
    switch (kind) {
    /*
     * The paint. Every one of these changes how the map LOOKS or what is
     * standing in it, and section 4.1 gives them zero architectural
     * divergence by contract - so attempting one while a structural band is
     * unmet is a compile spent to measure a zero that was known in advance.
     */
    case MAPGEN_EDIT_RESKIN:
    case MAPGEN_EDIT_RELIGHT:
    case MAPGEN_EDIT_SWAP_ITEM:
    case MAPGEN_EDIT_MOVE_SPAWN:
        return false;
    /* Withdrawn families; they move nothing because they do nothing. */
    case MAPGEN_EDIT_STAIRS_RAMP:
    case MAPGEN_EDIT_DROP_DETAIL:
        return false;
    default:
        /* Everything that moves solid, changes a route or rebuilds a room. */
        return true;
    }
}

const char *MapGenGeometryEdit_KindName(mapgen_edit_kind_t k)
{
    switch (k) {
    case MAPGEN_EDIT_RESKIN:      return "reskin";
    case MAPGEN_EDIT_STAIRS_RAMP: return "stairs-to-ramp";
    case MAPGEN_EDIT_STAIRS_LIFT: return "stairs-to-lift";
    case MAPGEN_EDIT_RELEVEL:     return "relevel";
    case MAPGEN_EDIT_DROP_DETAIL: return "drop-detail";
    case MAPGEN_EDIT_RELIGHT:     return "relight";
    case MAPGEN_EDIT_SWAP_ITEM:   return "swap-item";
    case MAPGEN_EDIT_ROOM_BLOCK:  return "room-block";
    case MAPGEN_EDIT_WIDEN_CONNECTOR: return "widen-connector";
    case MAPGEN_EDIT_OPEN_CONNECTOR:  return "open-connector";
    case MAPGEN_EDIT_TURN_BUNDLE: return "turn-bundle";
    case MAPGEN_EDIT_RESHAPE_ROOM: return "reshape-room";
    case MAPGEN_EDIT_SWAP_BUNDLES: return "swap-bundles";
    case MAPGEN_EDIT_RECOMPOSE_BUNDLES: return "recompose-bundles";
    case MAPGEN_EDIT_GRAFT_BUNDLE:      return "graft-bundle";
    case MAPGEN_EDIT_RECUT_ROOM:        return "recut-room";
    case MAPGEN_EDIT_PUSH_WALL:         return "push-wall";
    case MAPGEN_EDIT_MOVE_SPAWN:        return "move-spawn";
    case MAPGEN_EDIT_WINDOW:            return "window";
    case MAPGEN_EDIT_DIG:               return "dig";
    case MAPGEN_EDIT_PIT:               return "pit";
    case MAPGEN_EDIT_FLOOD:             return "flood";
    case MAPGEN_EDIT_SPAN:              return "span";
    case MAPGEN_EDIT_RELIQUID:          return "reliquid";
    case MAPGEN_EDIT_STAIRWAY:          return "stairway";
    case MAPGEN_EDIT_KINDS:       break;
    }
    return "unknown";
}

/* The Quake II surface flags this Module has an opinion about. A face that is
   sky, liquid, emitting, translucent or invisible is doing a job its texture
   name is part of, so it is never reskinned. */
#define SURF_LIGHT_BIT    0x0001
#define SURF_SKY_BIT      0x0004
#define SURF_WARP_BIT     0x0008
#define SURF_TRANS33_BIT  0x0010
#define SURF_TRANS66_BIT  0x0020
#define SURF_NODRAW_BIT   0x0080
#define SURF_HINT_BIT     0x0100
#define SURF_SKIP_BIT     0x0200

#define SURF_SPECIAL (SURF_LIGHT_BIT | SURF_SKY_BIT | SURF_WARP_BIT \
                    | SURF_TRANS33_BIT | SURF_TRANS66_BIT | SURF_NODRAW_BIT \
                    | SURF_HINT_BIT | SURF_SKIP_BIT)

#define CONTENTS_SOLID_BIT       0x00000001
#define CONTENTS_WATER_BIT       0x00000020
/* And the two that kill, for the pits this round digs: the same bits the
   engine's own `contents` field carries (`mapgen_reach.c`). */
#define CONTENTS_LAVA_BIT        0x00000008
#define CONTENTS_SLIME_BIT       0x00000010
/* Water, slime and lava together: what a drain uncovers, whichever it is. */
#define CONTENTS_LIQUID_BITS     0x00000038
#define CONTENTS_PLAYERCLIP_BIT  0x00010000
#define CONTENTS_DETAIL_BIT      0x08000000

/* What counts as a step, taken from how the engine moves rather than from
   taste: anything the player can walk up without jumping. */
#define STEP_MAX_RISE       18.0f
#define STEP_MIN_RISE       4.0f
#define STEP_MAX_HEIGHT     64.0f
#define STEP_MIN_WIDTH      48.0f
#define STEP_MIN_TREAD      8.0f
#define STEP_MAX_TREAD      128.0f
#define STAIR_MIN_STEPS     3
#define STAIR_MAX_STEPS     32

/* A ramp steeper than this is a wall with a slope on it: PM_CategorizePosition
   stops calling a surface ground below a normal Z of 0.7, so a replacement
   that crossed the line would be a staircase turned into an obstacle. */
#define RAMP_MIN_RUN_PER_RISE  1.6f

/*
 * How far a flood may move a pool's surface.
 *
 * The minimum was thirty-two when the operator moved water without looking at
 * the map: less than that was not worth a compile. With the basin rule below
 * it is the MAP that says how far the water may go, and on q2dm1 that is
 * twelve units on one pool and nothing on the other - so a minimum of
 * thirty-two means the family can only ever go DOWN there, and a fall of
 * forty-eight puts six pickups where no player can reach them. MEASURED: the
 * twelve-unit rise the basin allows is worth twenty-one permille of
 * divergence on its own, leaves no water standing in the air, and the map
 * stays playable. A waterline that moves is a change whatever its size.
 */
#define FLOOD_MIN  8
#define FLOOD_MAX  96

/*
 * And what a change of level IS.
 *
 * Two rounds got this wrong in opposite directions. First the operator moved
 * the water's own plane and left it standing in the air - twenty-five
 * vertical faces of water where the donor draws none, which the PO
 * photographed. Then the plane was capped by the basin's rim, and on q2dm1,
 * whose rims are eight and twenty units, that left the family able to move
 * the water twelve units: MEASURED, one standing place under water where the
 * flood the PO liked had covered a thousand.
 *
 * Water does not move its plane. It FILLS: every air cell below the new level
 * that is connected to the pool becomes water, and it stops where the walls
 * are, so a fill draws no vertical face by construction and needs no cap. And
 * it can be let out instead - the level drops, the basin's own walls appear,
 * and the way back up is built, because a pit with no way out is a trap and
 * MEASURED, a drain of forty-eight on q2dm1 put six of its eighty-three
 * pickups where no player could reach them.
 */
#define FLOOD_MIN_DEPTH   32.0f

/* The fill's own lattice, and what it may cost. A sixteen-unit cell is fine
   enough that the water follows the walls and coarse enough that q2dm1's
   lower half is a third of a million cells rather than ten million. And how
   far from the pool's own box the water may reach: a basin, not a map. */
#define FILL_CELL         16.0f
#define FILL_MAX_CELLS    600000u
/*
 * How many boxes one pool may be tiled into.
 *
 * Eight thousand, not two: the function returns ZERO rather than half a fill
 * when it runs out (`return room ? boxes : 0`), and half a fill is water with a
 * wall of air down one side. MEASURED 2026-09-12: q2dm1's big pool - one brush
 * -176 -464 144 .. 800 544 440, most of it inside rock - still reported «0
 * cells of 1500 wanted, 0 boxes» after the lattice was bounded, because its
 * own water tiles into more than two thousand boxes. Each is 24 bytes.
 */
#define FILL_MAX_BOXES    8192u
#define FILL_SPREAD       512.0f

/* What a relevel is dealt, at the smallest ambition. The fidelity doubles it
   at nothing and leaves it near this at ninety. */
#define RELEVEL_RISE_MIN   48
#define RELEVEL_RISE_MAX  160
#define RELEVEL_FALL_MIN  128
#define RELEVEL_FALL_MAX  288
/* How many times a fill may lower itself under something it cannot carry.
   Each pass finds the LOWEST blocker, so two is usually enough. */
#define RELEVEL_TRIES       6u
/* How much shallower a drain gets each time the pit it would dig turns out
   to be one a player could not climb out of. */
#define RELEVEL_FALL_STEP  32

/* The stairs a drain builds out of the basin it dug. */
#define STEP_RISE         16.0f
#define STEP_RUN          32.0f
#define STEP_WIDE        128.0f


/* What the operators measure against: the accepted map when there is one,
   the donor's own until the transaction hands one over. Defined with the
   plan's accessors, asked by every operator above them. */
static const struct mapgen_bsp_s *
ground_of(const struct mapgen_geometry_edit_plan_s *plan);

typedef struct {
    uint32_t brush[STAIR_MAX_STEPS];
    uint32_t count;
    int      axis;          /* 0 or 1: the horizontal it climbs along       */
    int      dir;           /* +1 or -1: which way is up                    */
    float    mins[3];
    float    maxs[3];
    uint32_t top_side;      /* a step's top face, for the replacement's skin */
    uint32_t wall_side;     /* and one of its vertical faces                */
} stair_t;

/*
 * One wall of one room, and how far into the rock it can go.
 *
 * Measured on the DONOR before anything is edited, because "how much solid is
 * behind this" is a question about the map as it was.
 */
/* A block to build, in world units, and the room it belongs to. */
typedef struct {
    float mins[3];
    float maxs[3];      /* the block itself                                  */
    float step[2][3];   /* a step onto it: mins then maxs                    */
    bool  has_step;
    /*
     * And an upper tier standing on it, inset, when the form has one.
     *
     * Two heights instead of one, which is the difference between a thing in
     * a room and a piece of architecture: a player walks up the step onto the
     * platform, and from the platform onto the tier, and from the tier he can
     * see and shoot across the room. A single box of the same total height is
     * a column, and a column is what the PO photographed five times on
     * 2026-09-08 and asked what it was for.
     */
    float tier[2][3];
    bool  has_tier;
    /*
     * HOLDS: a spawn point stands on this one's top.
     *
     * The second half of the purpose rule. A construction that leads nowhere
     * is refused - unless it is somewhere to arrive, which is what the PO
     * asked for of the niche he liked: «хочется туда положить доп респавн на
     * карте, чтобы там игрок мог респиться, и оформить его как другие точки
     * респавна» (2026-09-10, quake110 and quake111). Q2PRO-X draws the pad
     * from the entity itself, so a new `info_player_deathmatch` looks like
     * every other one.
     */
    bool  holds_spawn;
    /*
     * HOLDS, the other way: a pickup that was lying on a floor nearby is
     * carried up onto this one's top.
     *
     * The PO, 2026-09-10: «если мы делаем новые архитектурные изыски
     * подобного плана, то логично хоть в части из них делать не просто тупой
     * блок, а перемещать туда какие либо айтемы, которые просто валяются на
     * полу в другой части уровня - это было бы тогда хоть логичней». So a
     * construction can earn its place by being where something worth having
     * is now.
     *
     * The donor's entity index PLUS ONE, so that the zero a `memset` leaves
     * means "nothing" rather than "entity number zero".
     */
    uint32_t carries;
} room_block_t;

/*
 * A room's middle, and what stands there afterwards.
 *
 * The region is INSET from the room on every side: the ways in, the floor and
 * the ceiling are all outside it, so emptying it cannot open the map or take
 * away the surface a player arrives on. What goes back in is dealt from the
 * seed, which is what makes two seeds two different rooms.
 */
#define RECUT_MAX_BLOCKS   6
#define RECUT_FLOOR_CLEAR  16.0f   /* the floor is not the room's furniture  */
#define RECUT_CEIL_CLEAR   16.0f
/*
 * The smallest footprint that is still a room to rebuild.
 *
 * Was 256, and it was the single largest thing the family refused on: of the
 * fifty-one rungs offered per run on q2dm1, THIRTY-ONE died on this constant
 * and only two reached the point of dealing a construction. Identical on all
 * three seeds, because the region search does not depend on the seed.
 *
 * The reason it was 256 - "a corridor gutted leaves nothing to walk through" -
 * is now carried by things that measure it instead of guessing: the slide
 * refuses a region with a way through it, `region_has_climb` refuses a
 * construction that buries one, `room_to_pass` wants a player's width beside
 * every face that meets air, and the route guard judges the compiled map. What
 * is left for this number to say is only "can anything stand here": a
 * construction is at least 96 wide and wants 32 of clearance on each side, so
 * 160 is the floor and 192 leaves a walkway beside it.
 */
#define RECUT_MIN_SPAN    256.0f
#define RECUT_GROW_STEPS   64u     /* cells a face may travel outward        */
/*
 * How much room to spare the CLIMB question is asked over.
 *
 * ZERO, and both the number and the place it is declared are measurements.
 *
 * The place: the planner and `recut_room` have to ask the IDENTICAL box, or the
 * planner is answering a different question from the gate. They did not, and it
 * cost this family everything - MEASURED at ambition 25 on all three seeds, six
 * regions offered and six declined, every one of them for "there is a way
 * through the region on the map as it is now", a question the planner had
 * answered about a box thirty-two units smaller.
 *
 * The number: `region_has_climb` already grows what it is given by
 * CLIMB_MARGIN, 192 units on every side, deliberately - "a stair that starts
 * outside the box and ends inside it is still a stair the box lands on". A
 * margin here is added to that one, and thirty-two of it refuses every region
 * q2dm1 has: sixty-five positions x eight sizes x seventeen rooms, all "on a
 * way". A margin that refuses the whole map is not caution, it is a second
 * reach nobody asked for.
 */
#define RECUT_KEEP         0.0f
/*
 * How many places in the room a rung is offered before the family gives up on
 * it. One is the middle; the rest walk outward in rings of eight, and the
 * outermost ring lands on the edge of what grew.
 *
 * Four rings rather than two. The ring step used to be half the spare room per
 * ring, so ring two WAS the edge and there was nowhere further to go; with the
 * step scaled by the number of rings the same range is sampled four times as
 * finely, which is what a room with a staircase down one side needs to be
 * tried from the other.
 */
#define RECUT_RINGS         4u
#define RECUT_SLIDES       (1u + RECUT_RINGS * 8u)
/* How many places for one construction the region's floor is asked to offer
   before the draw. The room block's number, for the room block's reason. */
#define RECUT_SPOTS       256u

/* How far a construction's foot goes below the floor it stands on: enough
   that the seam between the two is inside solid rather than along a plane
   two surfaces share. */
#define BLOCK_BURY         16.0f
/* A wall narrower than this is a doorway, and pushing a doorway back is what
   widen-connector is for. */
#define PUSH_MIN_WIDTH    192.0f

/* ---- PIT: a hollow cut into a floor and filled with a liquid --------------- */

/*
 * The numbers, and where each of them comes from.
 *
 * SIDE     128 to 384 across. Smaller than a passage is a puddle nobody swims
 *          in; larger takes a room's whole middle, and the share below caps
 *          that anyway.
 * DEPTH    48 to 128, doubled toward fidelity 20 like the relevel's rise. A
 *          player swims out of anything he can reach the rim of, and the rim
 *          stands PIT_LINE_DROP over the water.
 * CLEAR    64 of the room's own floor round the hollow on every side, measured
 *          as "the floor out there is the same floor": that is what keeps it
 *          out of walls, off stairs and away from the edge of a ledge.
 * UNDER    16 of rock below its bottom, so a pit is never a hole into the room
 *          underneath.
 * LINE     the liquid's surface 8 below the rim - the donor's own numbers: the
 *          two pools of q2dm1 stand 8 and 20 under their rims.
 * SPAWN    128 from a hazard's rim to any player start: a spawn beside lava is
 *          a spawn kill, and the reach explorer cannot say so - it reports the
 *          lethal place as lethal and the start as fine.
 * SHARE    at most two fifths of a room's floor area, so a room stays a room.
 */
#define PIT_MIN_SIDE      128.0f
#define PIT_MAX_SIDE      384.0f
#define PIT_GRID           64.0f
#define PIT_MIN_DEPTH      48.0f
#define PIT_MAX_DEPTH     128.0f
#define PIT_WALL_CLEAR     64.0f
/*
 * APART is the gap between two PITS, and it is not the same number as the
 * margin from a room's wall.
 *
 * Thirty-two, because a pit's shell is sixteen thick: two pits that far apart
 * have their shells meet exactly and not overlap, which leaves a real rock
 * divider between them rather than the shared wall of ledger row 75.
 *
 * MEASURED 2026-09-12, and on this donor it changed NOTHING: at sixty-four and
 * at thirty-two the driver deals the same two pits out of its nine sites,
 * because every site left over OVERLAPS one already taken rather than merely
 * crowding it - the nine sit on a 64 grid inside one room. The number is right
 * for the reason above; what limits q2dm1 is how few sites survive «floor not
 * one level» at all, 142 refused of 194 tried, and that - not this gap - is why
 * no map in the batch carries lava.
 */
#define PIT_APART          32.0f
#define PIT_ROCK_UNDER     16.0f
#define PIT_SPAWN_CLEAR   128.0f
#define PIT_LINE_DROP       8.0f
#define PIT_CURB           16.0f
#define PIT_MAX_SITES      96u
#define PIT_ROOM_SHARE     40u

typedef struct {
    float    lo[3], hi[3];     /* the hollow: its bottom up to the room floor */
    float    line;             /* the liquid's surface                        */
    int32_t  contents;         /* water, slime or lava                        */
    char     liquid[MAPGEN_BSP_TEXNAME + 1];
    int32_t  liquid_flags, liquid_value;
    char     trim[MAPGEN_BSP_TEXNAME + 1];
    bool     hazard;           /* slime or lava: it gets a curb               */
    uint32_t room;
} pit_t;

/*
 * A FLOOD: the room's own floor, lowered where it is one level and filled.
 *
 * The pit's machinery with the pit's square taken out of it. The hollow is the
 * room's REAL floor mask on a 32-unit pitch, merged into as many boxes as the
 * shape takes, with a walkable margin left all round the room so its doorways
 * keep their floor and its exits keep working - that margin is why a flooded
 * room is still a room a player can be in, and it is also the only thing
 * holding the liquid, since it is the room's own floor slab that is left.
 *
 * MARGIN     96, three player widths of dry rim at the room's edge.
 * PITCH      32, the mask's own cell: a floor that steps by less than a step
 *            is one level, and the shape follows the architecture.
 * DEPTH      64..96 by fidelity. The surface stands LINE_DROP below the old
 *            floor, so a swimmer's head is at the rim and no liquid face is
 *            ever drawn against air (the pit's rule, measured at zero).
 * SHARE      at least this much of the room's own floor, or the hollow is a
 *            puddle again and the PO has said what he thinks of those.
 */
#define SUNK_PITCH         32.0f
#define SUNK_MARGIN        96.0f
#define SUNK_DEPTH_MIN     64.0f
#define SUNK_DEPTH_MAX     96.0f
#define SUNK_LINE_DROP      8.0f
#define SUNK_ROCK_UNDER    16.0f
#define SUNK_LEVEL_SLACK    8.0f
#define SUNK_SPAWN_CLEAR  128.0f
/*
 * 32 cells of 32 x 32 = 32 768 square units: a pool about 180 by 180, twice the
 * puddle the PO refused, and still well under the pools he pointed at.
 *
 * It was 48. Assignment 21 D12b, applied because the measurement required it:
 * after the step tolerance (D12) the arena still offered only 41 cells - it
 * retreats nine to keep the headroom of a passage at 880 800 336 that its shell
 * would otherwise bury, which is correct - and the third room offers 38 before
 * any retreat. The rejected 128-unit pit was 16 cells; the reference pools of
 * q2dm1 and q2dm4 (`screenshots/quake146.jpg`, `quake147.jpg`) are 100-200. 48
 * sat above two of the four rooms q2dm1 has that can take water at all. The
 * constant `SUNK_MIN_SHARE` is not touched (assignment 21 §4); what it is
 * compared with changed on the PO's word about the arena - see its comment.
 */
#define SUNK_MIN_CELLS      32u
/*
 * A quarter of the room's OWN floor, and the denominator is what makes that a
 * real bar rather than a slogan: the cells at the room's main level, not every
 * cell of its box. MEASURED 2026-09-12 - against the whole box all four
 * candidate rooms of q2dm1 failed at thirty per cent before a single cell was
 * refused for a reason of its own.
 *
 * And it is asked of what the room OFFERS, before its hollow retreats from a way
 * the shell would have walled up - the arena kept 41 of the 50 it offered and
 * was refused one cell under this bar for keeping a passage's headroom
 * (2026-09-13, rows 220-221). `mapgen_flood_worth_dealing` holds the rule.
 */
#define SUNK_MIN_SHARE     25u     /* per cent of the room's own floor       */
/*
 * How wide ONE piece of the hollow may be cut.
 *
 * MEASURED 2026-09-12, and this is the difference between the two floods q2dm1
 * offers at ambition 80: room 2, cut as 17 pieces of at most 384 units, compiles
 * SEALED with no water standing in the air; room 0, cut as 12 pieces up to 992
 * units wide, LEAKS - and its pointfile leaves the hollow and runs west along
 * the top of the floor slab as far as x=480, twelve hundred units outside the
 * carve, through space the donor has solid. `carve_box` splits a brush that
 * crosses its box and carries `CARVE_MAX_BRUSHES` of them; a piece as wide as a
 * room crosses the map's big slabs and their remainder beyond the box is what
 * goes missing. A passage is 128 wide and has never done this, so the hollow is
 * cut in pieces of that order and there are simply more of them.
 */
/*
 * What counts as a LONG brush, and how far one may reach past the hollow.
 *
 * 512 and 256: a brush wider than five hundred units is one of the map's own
 * slabs rather than a piece of furniture, and one that reaches more than two
 * hundred and fifty-six past the cut is one whose remainder the carve does not
 * keep. Both measured on q2dm1 - see the collection in `deal_floods`.
 */
/*
 * And how big a ROOM may be for its floor to be taken away at all.
 *
 * MEASURED 2026-09-12, after ten build cycles on one leak: q2dm1 offers two
 * floods at ambition 80, and the difference between them is size. Room 2 is
 * 384 by 704 units and compiles SEALED with no water standing in the air, at
 * every setting tried. Room 0 is 992 by 1504 and LEAKS at every setting tried -
 * one-cell shell and margin-wide, 960 cells and 592, 12 pieces and 32, with and
 * without the brush rules - and its pointfile never moved by a single unit,
 * walking out at 480 1600 through space the donor has solid all the way from
 * 440 down to -280. Seven hundred of the donor's 960 brushes cross that room's
 * floor and ten of them reach fifteen hundred units beyond it.
 *
 * A space that size is not a room whose floor can be replaced; it is the map's
 * own frame. So the family takes rooms it can seal and refuses the rest, and
 * says which it refused. 1024 is drawn between the two measurements.
 */
#define SUNK_MAX_SPAN    1024.0f
#define SUNK_BRUSH_LONG   512.0f
#define SUNK_BRUSH_REACH  256.0f
#define SUNK_MAX_LONG     512u
#define SUNK_MAX_PIECE    256.0f
#define SUNK_MAX_BOXES    512u
/*
 * And how many pieces the shell may take.
 *
 * One per ring cell, unmerged: the pieces have different tops, so merging them
 * would mean merging only equal ones and the code that does that is longer than
 * the code that does not. MEASURED 2026-09-12: a 30x40 grid whose mask is 960
 * cells has a ring of about 150, so two floods cost three hundred brushes on a
 * map that carries eleven hundred - and a cap that the ring silently hits is a
 * map that silently leaks, which is what 192 did.
 */
#define SUNK_MAX_SHELL    768u
#define SUNK_MAX_CELLS   8192u
#define SUNK_MAX_THINGS   512u
/*
 * How much room a thing standing on the floor takes, for the mask's purposes.
 *
 * The same thirty-two as `ITEM_ROOM` and for the same reason - a player
 * standing at a pickup occupies the space around it - but written here rather
 * than borrowed, because `ITEM_ROOM` is declared a thousand lines BELOW the
 * mask that needs it and a constant used before its definition is not a
 * constant. If one of the two ever moves, they are both about a player's width
 * and both say so.
 */
#define SUNK_THING_ROOM    32.0f

typedef struct {
    float    lo[3], hi[3];     /* the hollow's bounds, for the gates          */
    float    line;             /* the liquid's surface                        */
    float    floor_at;         /* the room's own floor, which is the hi z     */
    int32_t  contents;
    char     liquid[MAPGEN_BSP_TEXNAME + 1];
    int32_t  liquid_flags, liquid_value;
    char     trim[MAPGEN_BSP_TEXNAME + 1];
    bool     hazard;
    uint32_t room;
    uint32_t cells, room_cells;
    /* the shape, as x0 y0 x1 y1 per piece: every piece runs from `lo[2]` up
       to `floor_at`, so four numbers are the whole of it */
    uint32_t num_boxes;
    float  (*box)[4];
    /*
     * And the SHELL: the ring of cells that touch the hollow without being part
     * of it, each standing from the hollow's floor up to the room's.
     *
     * MEASURED 2026-09-12: with a bottom slab alone the first two floods
     * compiled to «**** leaked ****». A room's floor slab is thinner than the
     * hollow is deep, so under the walkable margin the cut runs out of rock and
     * the side of the hollow looks straight into the void the compiler fills
     * round the hull. The dig and the pit both learned this; this is the same
     * shell in the shape of a room.
     *
     * Five numbers per piece, not four: x0 y0 x1 y1 and its own TOP. A ring
     * cell is whatever the architecture put there - the margin's floor, a step
     * down to a doorway, a crate, or nothing at all - and a slab that rose to
     * the room's floor everywhere would wall up the step and the doorway with
     * it. Each piece stands from the hollow's floor up to the rock that is
     * already there, which is exactly as high as the seal needs to be.
     */
    uint32_t num_shell;
    float  (*shell)[5];
} flood_t;

/* Row 410: one pool made another liquid - its box, what it is and what it becomes, and the new liquid's look. */
typedef struct {
    float   lo[3], hi[3];
    int32_t from, to;
    char    texture[MAPGEN_BSP_TEXNAME + 1];
    int32_t flags, value;
    uint32_t brushes;
} reliquid_t;

/*
 * A SPAN (row 405, Fable's brief 5 W5): a bridge between two galleries - its deck, its rails, the two standing places
 * it joins, the walk between them before it and its own length, and what it wears.
 */
typedef struct {
    float    deck_lo[3], deck_hi[3];
    float    rail_lo[4][3], rail_hi[4][3];
    uint32_t num_rails;
    float    a[3], b[3];
    float    before, across;
    char     tex_deck[MAPGEN_BSP_TEXNAME + 1];
    char     tex_rail[MAPGEN_BSP_TEXNAME + 1];
} span_t;
#define SPAN_RAIL_HIGH_BOX 32.0f    /* SPAN_RAIL_HIGH, for the edit's box above the code that defines it */

/*
 * A STAIRWAY (brief 11 D1): its solid steps, its landing (solid to the floor: nothing floats), the room it stands in,
 * where a player starts up it and stands on top, and its purpose - the pickup moved onto the landing, or the ledge the
 * landing meets.
 */
#define STAIR_STEPS_MAX 12u
typedef struct {
    float    lo[3], hi[3];
    float    land_lo[3], land_hi[3];
    float    step_lo[STAIR_STEPS_MAX][3], step_hi[STAIR_STEPS_MAX][3];
    uint32_t num_steps;
    float    foot[3], top[3];
    float    high, wide;
    uint32_t room;
    bool     ledge;
    uint32_t move_entity1;        /* the pickup moved onto the landing, index + 1; 0 for a ledge */
    char     move_class[32];
    float    move_from[3], move_to[3];
    char     tex_tread[MAPGEN_BSP_TEXNAME + 1];
    char     tex_side[MAPGEN_BSP_TEXNAME + 1];
} stairway_t;
/* Set by `deal_annexes` (row 405, W5): some size found no rock site and its annexes were sought in the map's free
   air - the donor is an arena, and spans are dealt on it. */
static bool g_annex_built_in_air;

/* ---- DIG: a passage cut between two floors the donor already has ----------- */

/*
 * The numbers, and the three of them that are measurements rather than tastes.
 *
 * WIDE/HIGH    128 inside. A fight needs room; a 96 shaft feels like a duct.
 *              HIGH falls back toward HIGH_MIN where the rock does not hold
 *              128, because PO example (a) - the corridor under the arena -
 *              is 112 tall from its floor at 328 to its ceiling at 440, and
 *              refusing the thing he asked for on a constant is not an answer.
 * DROP_MIN     96, not the 128 the assignment asked for, and the reason is the
 *              same measurement: that arena floor is at 448 and the corridor
 *              floor at 328, a difference of 120. A player steps 18 and jumps
 *              about 45 more, so 96 is still a connection he cannot hop.
 * RISE/RUN     16 and 32. The rise is what `pmove` will climb (STEP_MAX 18);
 *              the run is what makes a staircase rather than a ladder.
 * LANDING      128 long, every 12 steps and at every bend.
 * SHELL        16 thick, the thinnest wall the compiler holds shut.
 */
#define DIG_WIDE        128.0f
#define DIG_HIGH        128.0f
#define DIG_HIGH_MIN     96.0f
#define DIG_SHELL        16.0f
/*
 * The sky skin's band round a dig (ledger rows 354-356): beyond the shell a gap
 * of air and an enclosure voxel of sky. A dig skinned this way owns the band;
 * no other dig may come into it, so digs one plan deals keep both their bands
 * between them (row 361, Fable's brief C2): 80 between interiors.
 */
#define SKY_SKIN_GAP     16.0f
#define SKY_SKIN_VOXEL    8.0f
#define DIG_DEALT_CLEAR  (2.0f * (DIG_SHELL + SKY_SKIN_GAP + SKY_SKIN_VOXEL))
#define DIG_RISE         16.0f
#define DIG_RUN          32.0f
#define DIG_STEP_MAX     18.0f
#define DIG_LANDING     128.0f
#define DIG_STEPS_PER_LEG 12u
#define DIG_DROP_MIN     96.0f
#define DIG_SPAN_MAX   1024.0f
/*
 * A dig has to SAVE something: the existing walk between its two ends must be at
 * least this many hundredths of the dig's own length.
 *
 * 125, and the number is a measurement rather than a preference. The assignment
 * asked for 200; MEASURED on the PO's own first example - the arena floor at
 * 1488 520 448 down to the corridor at 1280 600 328 - the existing walk is 142
 * per cent of the dig, because the stairs into that corridor are not far away.
 * A floor of 200 refuses the thing he asked for, so the floor is 125 and this
 * comment is the reason.
 */
#define DIG_RATIO_MIN   125u
/*
 * And what a dig scores when the walk finds NO existing route at all.
 *
 * That is the most valuable dig there is - a connection the map does not have -
 * and the first version of this refused it, which cost PO example (c) exactly:
 * «WATCHED dig c rocket->railgun: REFUSED - no existing walk between its ends
 * at all». It is scored high but BELOW a measured ratio above 900, and the
 * ledger counts them separately, because "no walk" can also mean the lattice
 * could not see a jump or a lift that a player can make.
 */
#define DIG_RATIO_NEW   900u
/* A `light` every this far along the ceiling, plus one over every landing. */
/* A dig lift's deck, and how far above the floor it rests when lowered: the
   body clear of the floor at every stop, the top a step up (see the FIT pass). */
#define DIG_DECK_THICK    8.0f
#define DIG_DECK_REST    10.0f
#define DIG_LIGHT_EVERY 128.0f
#define DIG_LIGHT        "150"
/*
 * And a LAMP that can be seen, which is a different thing from a light.
 *
 * MEASURED 2026-09-12 on the delivered mg_tunnels.bsp: 1036 of the 1037 world
 * faces inside the eight dig boxes carry a lightmap, so the tunnels were never
 * unlit - they were lit by invisible point lights of 150 while the rooms they
 * run between are lit by EMITTING SURFACES the donor draws at 10000 to 15000
 * (`e2u3/ceil1_4`, `ceil1_13`, `ceil1_14`, `wstlt1_5`). Seven emitting faces
 * lay inside all eight digs together against 215 outside, and the mean lightmap
 * luminance came out 23 inside against 44 over the rest of the map. The PO:
 * «поскольку это тоннели, то в них желательно также добавлять равномерно (но не
 * аляписто много) подсветки - лампы, чтобы от них был свет как раз».
 *
 * So a panel is built into the ceiling every 256 units - eight thick, 48 by 48,
 * wearing the texture its own end rooms are lit with and the VALUE the donor
 * draws that texture at. «Не аляписто много» is the 256: one panel per two
 * cells of corridor, and never in a mouth, on a stair's sloping ceiling or in a
 * lift's shaft.
 */
/*
 * And what a SHAFT is lit with, which cannot be a panel.
 *
 * MEASURED 2026-09-12 with the panels in: the mean lightmap luminance inside
 * the eight tunnels went from 23.0 to 72.0 against 45.3 over the rest of the
 * map - but four of the eight got no panel at all and stayed at 18.4, 27.3 and
 * 28.2, and all four are pure «hatch and lift» shafts with no flat run to build
 * a panel into. A shaft cannot have one: its ceiling is where the lift's deck
 * arrives, so a panel there is hidden by the deck exactly when the player is
 * under it, and its walls are the deck's own travel.
 *
 * So a shaft keeps the invisible fill and gets more of it. The PO asked for
 * light in the tunnels; in the one shape that cannot wear a lamp, light is what
 * he gets.
 */
#define DIG_LIGHT_SHAFT  "350"
#define DIG_LAMP_EVERY   256.0f
#define DIG_LAMP_SIDE     48.0f
#define DIG_LAMP_THICK     8.0f
/* Below this the donor is not lighting a room with it.
   Row 405 (Fable's brief 5 L1): 100, and the sky, the liquids and the warps kept out BY FLAG. It was 1000, which is
   q2dm1's lamp catalogue (its panels are driven at 10000..15000, its sky 300..500, its water 100): q3t2's emitting
   textures run 425..564 (`clangbounce_*`) and below, so no annex of mg_q3t2 found a panel and four of six stayed
   dark (mean luxel 4.5..30 against the donor's 40.7). */
#define DIG_LAMP_MIN_VALUE 100
#define DIG_MAX_LAMPS      24u
/* The curb around a hatch or a stairwell mouth, so the hole is visible from
   the floor it is cut in. */
#define DIG_CURB         16.0f
/*
 * How far a player may have to walk from one of the dig's two ends before the
 * air at that point stops counting as the dig's OWN space - PLUS the dig's own
 * horizontal span, which is the half of this that is not a constant.
 *
 * MEASURED: with a flat 256, PO example (a) is refused at 1208 448 448 - a point
 * on the arena's own floor, 290 units of walk from the upper end, while the dig's
 * footprint is 272 long - and the guard's rock fixture refuses nine of nine pairs
 * the same way. The air at the far mouth of a long passage is the passage's, and a
 * constant cannot know how long the passage is.
 */
#define DIG_OWN_SPACE   256.0f

/*
 * A WATCHED pair of endpoints: follow this dig through every stage of the plan
 * and say, in the ledger, which stage refused it.
 *
 * The PO named three places on q2dm1 and the assignment is explicit about what
 * happens when one of them cannot be dug: «name the refusing trace and the
 * coordinates - do not substitute silently». A tally of 441 pairs refused for
 * air is not that; this is. The guard sets one watch per example.
 */
#define DIG_WATCHES        4u
#define DIG_WATCH_NEAR   128.0f

/* A routed dig is a chain of cells; merged into runs, a long one with its
   landings and a lift is still well under this. */
#define DIG_MAX_SEGS     32u
#define DIG_MAX_STEPS    64u
#define DIG_MAX_LIGHTS   48u

typedef enum {
    DIG_SEG_STAIR = 0,    /* treads descending along `axis` in `dir`        */
    DIG_SEG_LAND,         /* a flat landing                                */
    DIG_SEG_SHAFT         /* vertical, with a func_plat in it              */
} dig_seg_kind_t;

typedef struct {
    uint8_t kind;
    int8_t  axis;         /* 0 or 1 for STAIR and LAND                     */
    int8_t  dir;          /* +1 or -1: the way the passage DESCENDS        */
    uint8_t steps;        /* STAIR only                                    */
    /*
     * A MOUTH: the rock between the room a routed passage starts from and its
     * first carved cell, cut away (`route_mouth`). Carved, shelled and floored
     * like a landing; no lamp hangs in it and no curb is built round it.
     */
    uint8_t mouth;
    /* a cell grown into a HALL (`dig_grow_halls`, ledger row 310) */
    uint8_t hall;
    /*
     * An INNER segment (ledger row 327): furniture of a room that is another
     * segment of the same dig - a storey's terrace or its flight. The room's
     * shell and carve contain it, so it has neither, and it hangs no lamp or
     * light of its own; a landing is laid solid from `base` up to its floor,
     * and a flight puts no rock back over its headroom.
     */
    uint8_t inner;
    /*
     * How much each tread rises, and how much headroom there is over it.
     *
     * The rise is NOT the family's constant: the number of steps comes from the
     * run the rock has available and the rise follows as `drop / steps`,
     * bounded above by what `pmove` will climb (DIG_STEP_MAX). A flight forced
     * to exactly 16 either refuses a passage the rock could hold or ends at the
     * wrong height.
     *
     * The headroom is DIG_HIGH where the rock allows it and as little as
     * DIG_HIGH_MIN where it does not - PO example (a)'s corridor is 112 tall.
     */
    float   rise;
    float   head;
    float   base;         /* INNER only: the floor it stands on            */
    /* The carved interior: from the lowest tread's top to the highest
       ceiling. This is also exactly the box the plan's trace gate samples, so
       the planner and the operator cannot disagree about what was proved. */
    float   lo[3];
    float   hi[3];
} dig_seg_t;

/*
 * One dig, decided at plan time on the donor and rebuilt by the operator
 * against the map as it is.
 *
 * The skins are held by NAME rather than as a side index, for the reason every
 * other family holds its identity that way: an accepted edit that drops a
 * brush renumbers every side after it.
 */
/*
 * Which of the four shapes a dig is, as an index, so the deal can prefer one the
 * map does not have yet. Named rather than enumerated because the shape is carried
 * as the string the ledger and the README print.
 */
static const char *const DIG_SHAPE_NAMES[] = {
    "shaft+lift", "stair", "ell", "stair+lift",
    /* and what the ROUTER lays, round through the rock (`dig_route`) */
    "tunnel", "tunnel+lift", "corridor"
};

static uint32_t shape_index(const char *shape)
{
    for (uint32_t i = 0; i < sizeof(DIG_SHAPE_NAMES) / sizeof(*DIG_SHAPE_NAMES);
         i++)
        if (!strcmp(shape, DIG_SHAPE_NAMES[i]))
            return i;
    return 0;
}

static bool shape_index_used(const bool *used, const char *shape)
{
    return used[shape_index(shape)];
}

static void mark_shape_used(bool *used, const char *shape)
{
    used[shape_index(shape)] = true;
}

typedef struct {
    float    from[3];          /* the standing spot up there, on its floor  */
    float    to[3];            /* and the one down here                     */
    uint32_t room_from, room_to;
    dig_seg_t seg[DIG_MAX_SEGS];
    uint32_t num_segs;
    bool     lift;             /* a shaft segment carries a func_plat       */
    bool     hatch;            /* the top opening is a hole in a floor      */
    uint32_t ratio;            /* existing route / dig length, x100         */
    float    length;           /* the dig's own walked length               */
    uint32_t steps, landings, lights;
    /* row 310: the halls grown on this passage, the cells the proof
       refused, and where the first of those breaks into space */
    uint32_t halls, hall_refused;
    uint32_t hall_met;         /* row 319: cells whose hall met their passage */
    float    hall_bad[3];
    /*
     * Which WATCH this dig answers, or UINT32_MAX.
     *
     * A watched pair is not merely reported - it is dealt FIRST. Assignment 14
     * says the PO's three examples «go into the candidate list of q2dm1 with
     * their ratios printed in the ledger - that is the guard's first case», and
     * a candidate list whose top six are other people's digs does not contain
     * them in any sense he can walk. The shortcut ratio still orders everything
     * else.
     */
    uint32_t watch;
    /* tried and put aside: it crossed a dig already dealt. Kept so the
       shape-first deal does not offer it again on the next round. */
    bool     skipped;
    char     shape[16];
    char     tex_wall_from[MAPGEN_BSP_TEXNAME + 1];
    char     tex_wall_to[MAPGEN_BSP_TEXNAME + 1];
    char     tex_floor[MAPGEN_BSP_TEXNAME + 1];
    char     tex_trim[MAPGEN_BSP_TEXNAME + 1];
    /* how much of its room each of the three skins covers, in square units:
       the ledger says why a dig wears what it wears (`dig_pick_skins`) */
    float    skin_area[3];
    /* the panel its ceiling is lit with, and the value the donor drives that
       texture at - empty when the donor lights nothing with a texture of its
       own, and then the passage keeps its point lights alone */
    char     tex_lamp[MAPGEN_BSP_TEXNAME + 1];
    int32_t  lamp_value;
    /*
     * An ANNEX's pickups (ledger rows 315, 324): the donor entity moved into each
     * room, PLUS ONE - zero for every other dig, so a zeroed dig moves nothing -
     * with its class and the two origins the plan chose. A wing moves two.
     */
    uint32_t move_entity1[2];
    char     move_class[2][32];
    float    move_from[2][3], move_to[2][3];
    /*
     * Row 405 (Fable's brief 5 W2.3): an annex BUILT in the map's free air rather than dug out of rock - cor has no
     * rock inside its sky box, only plates. Its shell is its building: sealed on every side the map's air touches
     * but the doorway, no sky skin, and G5-7's trim does not pull it back from the old air it stands in by design.
     */
    bool     air;
    /*
     * Brief 9 D3 (Fable, 05.10; the PO: «квадратные комнаты с оружием или армором по середине ... Где разнообразие?»):
     * an annex's room drawn per room from independent parts - its floor (flat, a rim, a gallery with its steps),
     * where its pickup stands (a dais in the middle, the floor near the far wall, the gallery, between two columns),
     * its columns (0, 2, 4) and its trims (none, the lintel band, both bands). `pat_set` false: the one room of row
     * 377 (a dais, both bands) - a wing's rooms, a test seam's.
     */
    bool     pat_set;
    uint8_t  pat_floor, pat_pickup, pat_columns, pat_trims;
    /* brief 9 D2: the second map whose room's skin it wears ("" - the host room's, as always) */
    char     skin_of[32];
    /*
     * Brief 9 D1: a ROOM OF THE SECOND MAP ("room-of"): dug like an annex - its mouth through our wall, its room the
     * size of that room - and then what that room holds inside its walls brought in from the second map (its
     * brushes, turned and moved into place, and its lights): `room_src` its geometry, the masks of what crosses (one
     * byte a brush and an entity of it), the pivot it turns about, the quarter turns and the offset after.
     */
    const mapgen_geometry_t *room_src;
    uint8_t *room_brushes, *room_entities;
    float    room_pivot[3], room_offset[3];
    uint32_t room_turns, room_of, room_carried, room_lights;
    /* row 412, the PO on mg_10_45d: the room as CUT out of its map, owned here (`room_src` points at it) */
    mapgen_geometry_t *room_own;
    uint32_t room_fell;         /* what of the cut did not stand and did not come */
} dig_t;

/* One deathmatch start, and where it is being sent. */
typedef struct {
    uint32_t entity;
    float    to[3];
} spawn_move_t;

typedef struct {
    float    lo[3], hi[3];         /* the region emptied of world geometry   */
    /*
     * And what stands in it afterwards - the ROOM BLOCK's own kind, not a
     * pair of corners.
     *
     * A pair of corners is a box, and a box is not a construction: the tier
     * on top of one was held as a second box, dropped onto the ground by
     * itself at apply time, and landed INSIDE its own parent. Held this way
     * the tier and the step are part of the thing they stand on, one lift
     * moves the whole of it onto its floor, and `block_stands` - the
     * builder's own predicate, the one the room block has used since
     * 2026-09-08 - is the single answer to whether it may be built.
     */
    room_block_t block[RECUT_MAX_BLOCKS];
    uint32_t num_blocks;
    uint32_t room;
    /*
     * The floor the region stands on, measured under its seed.
     *
     * Kept because the region is emptied from just above this line upward: a
     * construction inside it may only rest on ground BELOW the line, or the
     * hollow takes its floor away and the thing hangs.
     */
    float    floor_at;
} recut_t;

/*
 * One wall beside one way through, and how far back it may go.
 *
 * Held as a PLANE and a point on it rather than as a side index: an accepted
 * edit that dropped a brush moves every index after it, and an operator that
 * then widened whatever now wears that number would be carving somewhere
 * nobody looked.
 */
typedef struct {
    float    normal[3];
    float    dist;
    float    center[3];
    float    depth;          /* how far back into the rock, in units      */
    uint32_t room;           /* which bundle's way out this belongs to    */
    uint32_t peer;
} widen_t;

/*
 * WHAT a pane is, and there are four of them.
 *
 * The PO shot the glass of three delivered maps and saw nothing there at all:
 * `SP_func_explosive` frees itself at spawn when `deathmatch` is set
 * (`src/game/g_misc.c:740`, id's own code from 1997), q2dm1 is played as a
 * deathmatch map, and the pane was deleted before his first frame. Breakable
 * glass in deathmatch is therefore UNAVAILABLE and we do not go around it -
 * «игру мы и не можем менять - карты должны работать у всех клиентов».
 *
 * He answered it himself and the answer is a family: «если нельзя
 * разбиваемое, то точно можно просто обычное прозрачное. А открывать его
 * тогда как дверью: подошёл к двери, на полу кнопка, наступил на неё -
 * открылось», «проявляйте ТВОРЧЕСТВО!»
 *
 * So a pane is dealt as one of four things, every one of them built out of
 * entities the STOCK game keeps in deathmatch - read out of `src/game/`
 * rather than assumed, which is the whole lesson of the round before this:
 *
 *   WINDOW  a world brush wearing base1's glass. No entity at all, so there
 *           is nothing for any game to delete. You look through it and it is
 *           a wall.
 *   DOOR    a `func_door` with neither `health` nor `targetname`, which is
 *           exactly the case where `SP_func_door` spawns its own approach
 *           trigger (`g_func.c:1157-1160`). Walk up: it slides away and
 *           closes behind you.
 *   PLATE   a `func_door` with a `targetname` - so NO approach trigger - plus
 *           a visible `func_button` lying on the floor in front of it. Step
 *           on the plate and the glass opens. `G_UseTargets` fires every
 *           entity whose targetname matches (`g_utils.c:211-224`), so one
 *           plate opens a whole row.
 *   SHOT    a `func_door` with `health 10`, `wait -1` and `sounds 1`, whose
 *           `target` is a `target_speaker` carrying base1's own
 *           `world/brkglas.wav`. Shoot it: the shatter rings out, the pane
 *           drops out of sight and is gone for the rest of the match. That is
 *           «игроки стреляют, стёкла разлетаются и дают проход» on a stock
 *           server; only the debris is missing, and the debris is exactly
 *           what the stock game refuses us.
 *
 * Zero is WINDOW, so a `memset` leaves the pane that cannot fail.
 */
typedef enum {
    GLASS_WINDOW = 0,
    GLASS_DOOR,
    GLASS_PLATE,
    GLASS_SHOT,
    GLASS_SHAPES,      /* the four above are the ones a schedule deals */
    /*
     * And the fifth, which is RETIRED rather than gone: base1's own
     * `func_explosive`, to the value, which the game frees at spawn in
     * deathmatch. Only `MapGenGeometryEdit_DealBreakableGlass` reaches it,
     * and only so the deathmatch launch guard can regenerate a map whose
     * panes are supposed to be missing.
     */
    GLASS_BREAK
} glass_shape_t;

/* The most floor plates one pane may have: one each side, because a pane
   between two rooms is approached from either of them. */
#define GLASS_PLATES 2u

/*
 * One wall, and the doorway to be cut through it.
 *
 * Held as the wall's own BOX and the opening's extent rather than as a brush
 * index, for the reason widen_t is held as a plane: an accepted edit that
 * dropped a brush moves every index after it, and an operator that then cut a
 * doorway through whatever now wears that number would be opening a hole
 * somewhere nobody looked.
 *
 * `thin` is the axis the wall is thin on - the one a player walks through -
 * and `across` is the horizontal axis the doorway is wide on. The third is
 * always up.
 */
typedef struct {
    float    mins[3];        /* the wall box, as the donor drew it        */
    float    maxs[3];
    int      thin;           /* 0, 1: the axis the doorway goes through   */
    int      across;         /* the other horizontal axis                 */
    float    lo;             /* the opening, along `across`               */
    float    hi;
    float    top;            /* the opening's head                        */
    /*
     * How far the opening's foot is ABOVE the wall's base.
     *
     * Zero is a doorway, which is what `open-connector` cuts. Anything else
     * is a window, and the number is chosen so that the hole cannot be a
     * route: at 96 units a player can neither step onto the sill nor jump
     * onto it, and neither can the reachability walk, so the family adds a
     * view without adding a way through - and the glass in it does not have
     * to be understood by anything that counts routes.
     */
    float    sill;
    /*
     * How many PANES, side by side along `across`, starting at `lo`.
     *
     * The PO asked for this in as many words: «можно и разные варианты
     * пробовать - делать длинные окна со стёклами и (или) много окон со
     * стёклами стоящими рядом - в игре игроки стреляют, стёкла разлетаются и
     * дают проход - интересно для геймплея будет!!!» Each pane is its own
     * `func_explosive`, so they break one at a time and a row of three is
     * three separate holes to make.
     *
     * Zero means one, so a `memset` leaves a single pane rather than none.
     */
    uint32_t panes;
    /*
     * WHICH of the four shapes this pane is, and a ROW is one shape for the
     * whole row: a door row is three doors with three approach triggers, a
     * plate row shares one `targetname` so one plate opens all three, and a
     * shot row is three doors with three speakers - breaking one leaves the
     * others standing.
     *
     * Dealt by the seed and weighted by ambition. Zero is `GLASS_WINDOW`.
     */
    uint32_t shape;
    /*
     * Which way a moving pane goes, and it is a MEASUREMENT rather than a
     * taste: the pane has to be inside rock for the whole of its travel or
     * the player watches it hang in the air beside the hole.
     *
     * `true` is up (`angle -1`), `false` is down (`angle -2`). A window has
     * 96 units of sill under it and a glazed doorway has the whole wall over
     * it; where NEITHER holds, the plan deals `GLASS_WINDOW` instead, because
     * the only third direction is along the wall behind a 16-unit jamb and a
     * pane that hides 16 units of its 68 is worse than a pane that does not
     * move.
     */
    bool     slide_up;
    /*
     * Where the floor plates go, for `GLASS_PLATE`: the centre of the top
     * face of each, already dropped onto the floor the donor has there.
     *
     * How FAR from the pane reads ambition, because the PO asked to see more
     * the further a fork is from its donor: at fidelity 90 the plate lies at
     * the pane, and at 20 it can be across the room, so he watches the glass
     * open under his foot from the far side.
     */
    uint32_t num_plates;
    float    plate[GLASS_PLATES][3];
} opening_t;

/*
 * How much wall a doorway leaves standing, and how big a doorway is.
 *
 * The jamb and lintel are what keep the three remaining pieces real brushes
 * and the wall sealing everywhere it did before. Sixty-four by ninety-six is
 * the doorway every fixture in this repository uses and is comfortably more
 * than the thirty-two by fifty-six a player occupies.
 */
#define DOOR_WIDE     64.0f
#define DOOR_TALL     96.0f
#define DOOR_JAMB     16.0f
#define DOOR_LINTEL   16.0f
/* A wall, not a block: thinner than this is trim, thicker is architecture a
   doorway would tunnel through rather than pass. */
#define WALL_THIN_MIN  8.0f
#define WALL_THIN_MAX 80.0f
/* Two sides of a doorway a player can step between. */
#define DOOR_STEP     24.0f

/*
 * A window, in numbers.
 *
 * SILL is the one that matters and it is not a taste: a Quake II player steps
 * 18 units and jumps about 54, so a foot 96 units up is out of reach from the
 * floor on either side. The rest is what a window looks like - a bit wider
 * than tall, a jamb each side, a course of wall over the head.
 */
#define WINDOW_SILL   96.0f
/*
 * MEASURED on q2dm1's 923 box brushes, 1080 of whose faces are thin enough to
 * be a wall: a 96 by 96 opening needs 128 units across and 208 up and only 29
 * walls have both, of which 12 reach the air test. At 64 by 64 it is 71 walls.
 * A porthole is what this donor has room for, and a porthole is a window.
 */
#define WINDOW_TALL   64.0f
#define WINDOW_WIDE   64.0f
#define WINDOW_JAMB   16.0f
#define WINDOW_HEAD   16.0f
/*
 * The MULLION between two panes of a row, and it used to be a PIER of 32.
 *
 * The PO walked a three-pane row on 2026-09-11 and asked «зачем тут три
 * стекла, если окно только одно?» - and he was right about what he saw: three
 * holes with thirty-two units of bare wall between them are three windows, not
 * one window with three lights. Sixteen is a mullion, and with the frame's own
 * plate over it (`WINDOW_FRAME_*` below) the row reads as one opening.
 */
#define WINDOW_PIER   16.0f
/*
 * How thick the PANE is, and it is base1's number rather than a choice.
 *
 * The delivered panes were 16 thick in the doorway and 32 in the row - the
 * pane FILLED the run of rock - and both big faces wore the glass. Through the
 * front face the player sees the back face thirty-two units behind it, and as
 * the camera moves the two translucent copies slide over each other: that is
 * «стёкла дрожат, рассыпаются на пиксели» exactly, and it is MEASURED out of
 * the delivered files (`mg_glass.bsp`: 640..656 and 1248..1280).
 *
 * base1's own pane - the one the PO named - is model `*20` at
 * `mins -72 136 16 maxs 128 144 112`: two hundred wide, ninety-six tall and
 * EIGHT thick. Read out of PAK0, not remembered.
 */
#define WINDOW_GLASS_THICK   8.0f
/*
 * The FRAME, which is what turns a hole with glass in it into a construction.
 *
 * «стекло - это часть физической поверхности, оно должно по салазкам ездить
 * так, чтобы было понятно, что это конструкция, и у него должна быть рама»
 * (PO, 2026-09-11).
 *
 *   WIDE    the frame band around the opening: jambs, head and sill.
 *   PROUD   how far it stands out of the wall on EACH side. Eight, because a
 *           frame flush with the wall is paint and the PO can tell.
 *   RAIL    the groove the pane runs in: the frame's proud plate stops this
 *           far short of the glass on each jamb, so the wall's own face is
 *           left as a recessed strip eight wide and eight deep down both
 *           sides of the pane. «по салазкам».
 *   HOUSING how far the box the pane slides INTO stands out of the wall. A
 *           pane that sinks into bare rock is «уезжать в пол магическим
 *           образом»; a pane that sinks into a visible metal box is a sash.
 *           Tried at 24, then 16, then PROUD, because the box has to fit in
 *           the air the donor has beside the wall.
 */
#define WINDOW_FRAME_WIDE   16.0f
#define WINDOW_FRAME_PROUD   8.0f
#define WINDOW_RAIL          8.0f
#define WINDOW_HOUSING_DEEP 24.0f
/*
 * How far a MOVING pane is sunk into the jambs, the sill and the head.
 *
 * A pane cut exactly to its opening has four edge faces lying ON the reveal the
 * grid cut: a brush model's faces coplanar with the world's, which the renderer
 * draws in whichever order the depth buffer rounds to. MEASURED in the delivered
 * mg_glass (2026-09-11): 768 and 512 square units of pane edge lying on the jamb,
 * the head and the floor - «стёкла дрожат, рассыпаются на пиксели». Four units
 * into the solid on every edge puts every edge face INSIDE the wall, where
 * nothing is ever drawn over it. A world window needs none of this: the compiler
 * merges coplanar world faces itself.
 */
#define WINDOW_PANE_BURY     4.0f
/* The most panes one window may have. Three reads as a row; more, on a wall
   q2dm1 has, reads as a missing wall. */
#define WINDOW_PANES   3u
/* How often along a wall a pane is offered, and how many places one wall may
   be asked about. Sixty-four is a pane's own width. */
#define WINDOW_STEP        64.0f
#define WINDOW_MAX_PLACES  32u
/*
 * The glass, COPIED FROM base1 rather than invented, because that is the pane
 * the PO named: «стёкла вообще могут разбиваться как на base1 карте - это
 * вообще круто было бы... игроки стреляют, стёкла разлетаются и дают проход».
 *
 * base1's own, read out of PAK0 (`maps/base1.bsp`, entity
 * `{ "model" "*20" "target" "t78" "dmg" "0" "health" "10" "mass" "800"
 * "classname" "func_explosive" }`, its faces wearing `e1u1/wndow0_3` with
 * surface flags 0x10):
 *
 *   TEXTURE  `e1u1/wndow0_3` - a pane with the Strogg emblem etched into it.
 *            The first version of this family used `e2u3/window1`, which is a
 *            near-black featureless texture: extracted from PAK0 and looked
 *            at, it is a dark grey noise field, and at 33 per cent opacity
 *            there is nothing to see. The PO's words were «никаких зеркал тут
 *            я не вижу» (quake130), and he was describing exactly that.
 *   FLAGS    SURF_TRANS33, as base1 has it. The compiler turns a solid brush
 *            wearing a translucent skin into CONTENTS_WINDOW by itself
 *            (q2tools-220 src/map.c), which is what a pane should be: the
 *            player cannot walk through it, vis does not seal on it, and the
 *            renderer draws what is behind.
 *   HEALTH   10, as base1 has it. This was 100 - the game's own default for a
 *            `func_explosive` with no health of its own - and 100 is about two
 *            rockets. He shot the pane and nothing happened. Ten breaks to a
 *            single shot from anything.
 *   MASS     800, as base1 has it. `func_explosive_explode` throws one debris
 *            chunk per hundred of mass, so 800 showers and 75 barely puffs.
 *   DMG      left unset, as base1's second explosive is not: a pane that
 *            explodes in your face is a trap rather than a window.
 *
 * A brush model does not SEAL the map, which is why the interior test below is
 * the family's safety property and not a nicety.
 */
/*
 * And the texture is NOT base1's any more, because the PO asked the obvious
 * question: «у левого стекла зачем-то кусок текстуры какого-то логотипа
 * наклеен, да ещё и обрезано - зачем так? И при чём тут base1, когда мы
 * говорим про q2dm1-форк?»
 *
 * He is right twice. `e1u1/wndow0_3` is 128x128 with the Strogg emblem filling
 * it; a pane 64 wide and 64 tall anchored to the WORLD origin shows whichever
 * quarter of the emblem its coordinates happen to land on, so each pane of a
 * row shows a different fragment. And base1 is another unit's wall.
 *
 * MEASURED over all twenty-four window/glass WALs in PAK0, through the game's
 * own palette: `e2u3/window5_1` is 128x128, mean luminance 71.1 of 255 - the
 * brightest plain glass there is - with a spread of 5.5, which is streaked
 * glass and no emblem (the emblem pane's spread is 8.8, and the near-black
 * `e2u3/window1` the first version used has a mean of 34.2). It lives in the
 * `e2u3` unit, which is the unit sixty of q2dm1's own sixty-five texture names
 * belong to, and it really is in PAK0 - checked, because thirteen of the
 * donor's OWN names are not.
 *
 * It is also anchored to the PANE's corner rather than to the world, below, so
 * that a row of three shows the same glass three times instead of three
 * different crops of one picture.
 */
#define WINDOW_GLASS_TEXTURE "e2u3/window5_1"
#define WINDOW_GLASS_FLAGS   0x00000010   /* SURF_TRANS33, as base1 */
#define WINDOW_GLASS_HEALTH  "10"
#define WINDOW_GLASS_MASS    "800"
/*
 * The frame's skin: `e2u3/metal5_1`, which is the DONOR's own and not a name
 * that sounds metallic. MEASURED: it is in q2dm1's texinfo and wears 22 of its
 * 3282 faces, it is 128x128, mean luminance 41.2, and the extracted image is a
 * riveted metal plate. The floor plate has worn it since 2026-09-10.
 */
#define WINDOW_FRAME_TEXTURE "e2u3/metal5_1"

/*
 * A pane that MOVES, in numbers, and every one of them is read off the stock
 * game rather than chosen.
 *
 * LIP is the only one that needs an argument. `SP_func_door` computes the
 * travel as `DotProduct(abs_movedir, size) - lip` and turns a lip of ZERO
 * into 8 (`g_func.c:1106-1113`), so a pane with the default lip would stop
 * eight units short and leave a strip of glass across the opening. A NEGATIVE
 * lip lengthens the travel instead: -4 takes the pane its own height plus
 * four, which is out of sight with a margin no player can see through.
 *
 * SPEED 200 for a door a player walks into - it is doubled in deathmatch
 * (`g_func.c:1097`), so 400 in the game, about a fifth of a second for a
 * 64-unit pane - and 400 for the shot one, because glass that has just been
 * shot should be GONE rather than gliding.
 *
 * The plate: `angle -2` so it sinks INTO the floor, `lip 4` so it sinks four
 * of its eight units (`SP_func_button` defaults the lip to 4 as well, and
 * saying it is what makes the number a decision), `wait 1` so it springs back
 * quickly and can be stepped on again.
 */
#define GLASS_DOOR_LIP       "-4"
#define GLASS_DOOR_SPEED     "200"
#define GLASS_DOOR_WAIT      "3"
#define GLASS_SHOT_SPEED     "400"
#define GLASS_SHOT_HEALTH    "10"
/*
 * How long a SHOT pane stays down before it comes back, in seconds, and the
 * range it is dealt from.
 *
 * It was `wait -1`: shot out and gone for the match. The PO: «Выстрел опускает
 * стекло, а как его обратно поднять - непонятно. Нужно, чтобы оно само
 * поднималось, и не ровно через 10 секунд, а варьировалось от карты к карте -
 * от 2 до 30».
 *
 * VERIFIED_SOURCE, twice over: `door_hit_top` schedules `door_go_down` only
 * when `moveinfo.wait >= 0` and the delay is `wait * BASE_FRAMERATE` frames -
 * seconds (`g_func.c:822-835`); and `door_go_down` puts `takedamage` and
 * `health` back from `max_health` (`g_func.c:849-862`), which `SP_func_door`
 * sets from `health` (`g_func.c:1128-1132`) - so the pane that came back can
 * be shot again, without one line of our own anywhere.
 *
 * Dealt ONCE PER MAP, which is what «варьировалось от карты к карте» asks for:
 * every shot pane on one map shares one number, and two maps have two.
 */
#define GLASS_SHOT_WAIT_MIN   2u
#define GLASS_SHOT_WAIT_MAX  30u
/*
 * The floor plate: 16 tall with a 4-unit bevel, and it was 8 tall and flat.
 *
 * Nobody in the 2026-09-11 videos stepped on one or looked at one. Sixteen is
 * a plate a player trips over rather than a tile, and the bevel - a second,
 * inset course on top - is what makes it read as a pressure plate instead of a
 * patch of different floor. `SP_func_button` computes its travel as
 * `size - lip` (`g_func.c:718-730`), so with `lip 4` a 16-tall plate sinks 12
 * of its 16: it visibly goes down.
 */
#define GLASS_PLATE_TALL    16.0f
#define GLASS_PLATE_BEVEL    4.0f
#define GLASS_PLATE_WIDE     64.0f
#define GLASS_PLATE_ANGLE    "-2"
#define GLASS_PLATE_LIP      "4"
#define GLASS_PLATE_WAIT     "1"
/*
 * The plate's skin, and it is NOT glass: «на полу кнопка» is a thing he has
 * to be able to find.
 *
 * From the DONOR's own palette, so a stock server has it: `e2u3/metal5_1` is
 * one of q2dm1's own 65 textures, it really is in PAK0 - thirteen of that
 * donor's names are not, which is why this was checked rather than assumed -
 * and the extracted image is a riveted metal plate at mean luminance 41 of
 * 255 against the 34 of the floor beside it.
 */
#define GLASS_PLATE_TEXTURE  "e2u3/metal5_1"
/* base1's own breaking glass, out of PAK0: `sound/world/brkglas.wav`. The
   speaker plays it POSITIONED at its own origin, so the origin has to be in
   air rather than in the rock the pane sits in. */
#define GLASS_SHOT_NOISE     "world/brkglas.wav"
/* How far out of the wall the speaker stands: clear of the reveal, and well
   inside the room. */
#define GLASS_SPEAKER_OUT    24.0f
/* How far from the pane a plate may lie at the widest search, and the step
   the search walks in. One plate at the pane is fidelity 90; the whole room
   is fidelity 20. */
#define GLASS_PLATE_STEP     64.0f

/* Why an operator declined, recorded on the way out. Declared here because the
   widen declines three levels above where the slot is defined. */
static bool decline(const char *why);

/* Is there a pickup, a start or any other placed thing in this box? Declared
   here because the window's frame and housing ask it a thousand lines above
   where the room block's own answer lives. */
static bool buries_something(const mapgen_bsp_t *donor, const float lo[3],
                             const float hi[3]);
/* How far a moving pane travels when it opens: its own height plus the four
   units a lip of -4 adds. Declared here for the same reason - the housing is
   built beside the frame, above where the shapes live. */
static float glass_travel(const opening_t *o);
/* The floor under a point and the first solid above it, both probed against the
   compiled map. Declared here because the dig's layout asks them a thousand
   lines above where the opening family defines them. */
static float donor_floor(const mapgen_bsp_t *donor, float x, float y,
                         float from_z, float reach);
static float donor_ceiling(const mapgen_bsp_t *donor, float x, float y,
                           float from_z, float reach);
static bool donor_air(const mapgen_bsp_t *donor, float x, float y, float z);
/* Every DIG this donor offers, dealt into the schedule. Declared here because
   the planner calls it three thousand lines above where it lives, beside the
   operator it shares its boxes with. */
static void deal_digs(mapgen_geometry_edit_plan_t *plan,
                      const mapgen_geometry_t *donor,
                      const mapgen_bsp_t *ground, uint64_t seed,
                      size_t ceiling);
static void deal_pits(mapgen_geometry_edit_plan_t *plan,
                      const mapgen_geometry_t *donor,
                      const mapgen_bsp_t *ground, uint64_t seed,
                      size_t ceiling);
/* And every ROOM this donor offers to flood, which is the pit's answer to
   «на весь размер комнаты». Declared here for the same reason. */
static void deal_floods(mapgen_geometry_edit_plan_t *plan,
                        const mapgen_geometry_t *donor,
                        const mapgen_bsp_t *ground, uint64_t seed,
                        size_t ceiling);
static char g_liquids[24];
static int32_t liquid_named(const char *name, size_t len);
static void deal_reliquids(mapgen_geometry_edit_plan_t *plan, const mapgen_geometry_t *donor, uint64_t seed,
                           size_t ceiling);
static bool build_reliquid(mapgen_geometry_t *candidate, const reliquid_t *rq);

/* How much wider a lower fidelity searches. Declared here because the planners
   read it and it is defined beside `ambitious`, which it corrects. */
static uint32_t breadth(const mapgen_geometry_edit_plan_t *plan);
/* How deep a way through goes back into the rock at this fidelity. Beside
   `breadth`, for the same reason. */
static float widen_depth(const mapgen_geometry_edit_plan_t *plan);

/* Asked by the planner, answered beside the operator that acts on them. */
static bool brush_is_box(const mapgen_geometry_t *g,
                         const mapgen_geometry_brush_t *brush,
                         float mins[3], float maxs[3]);
static bool opening_is_safe(const mapgen_bsp_t *donor, opening_t *o);
static bool opening_is_safe_why(const mapgen_bsp_t *donor, opening_t *o,
                                const char **why);
/* The window's own predicate: the run of rock between two spaces. Declared
   here because the deal asks it, far above where the operator lives. */
static bool window_run(const mapgen_bsp_t *donor, int thin, int across,
                       float from, float lo, float hi, float foot, float head,
                       float *near, float *far, const char **why);
/*
 * WHICH of the four things this pane is, decided once, at plan time, on the
 * donor.
 *
 * At plan time because every shape but the plain window is a MEASUREMENT: a
 * sliding pane needs rock for the whole of its travel and a plate needs a
 * floor it can lie on with a line of sight to the glass. Deciding in the
 * operator would mean the ledger said one thing and the map held another.
 *
 * Declared here because the two deals are a thousand lines above the probes
 * they need.
 */
static void deal_glass_shape(const mapgen_geometry_edit_plan_t *plan,
                             uint64_t *stream, const mapgen_bsp_t *donor,
                             opening_t *o, const char **why);
/* What a pane's shape is called, for the plan's own ledger. */
static const char *glass_shape_name(uint32_t shape);
static mapgen_geometry_result_t add_box_of_model(mapgen_geometry_t *g,
                                                 const mapgen_geometry_side_t *pattern,
                                                 const float mins[3],
                                                 const float maxs[3],
                                                 int32_t contents,
                                                 uint32_t model);
/* Declared here because the window is cut beside the doorway, above the box
   builders it shares with the rest of the module. */
static mapgen_geometry_result_t add_box_of(mapgen_geometry_t *g,
                                           const mapgen_geometry_side_t *pattern,
                                           const float mins[3],
                                           const float maxs[3],
                                           int32_t contents);

/*
 * How close a construction may come to a way through the map.
 *
 * ZERO, and the number is the gate's own: it counts a climb as lost when the
 * candidate turns it into something a player cannot stand on, so the rule the
 * operator needs is "do not bury one" and nothing wider. Room to USE the
 * stair is a different question and `room_to_pass` already asks it - a
 * player's width beside every side of the construction that faces air.
 *
 * MEASURED, and this is why the number was 48 and then 96 before it was 0:
 * the gate was comparing against the donor's own compiled file, and the
 * ROUND TRIP through brushes and back loses one climb place of q2dm1 all by
 * itself. Every operator was being charged with it, and widening this was
 * chasing a compiler's arithmetic. With the gate judging against the map its
 * own compile produces, the honest number is the honest rule.
 */
#define CLIMB_KEEP    0.0f
#define BLOCK_TRIES  64u
/* How many legal places in one room the planner will hold to draw from. */
/*
 * Whether the room block is DEALT into the schedule. It is not.
 *
 * The operator builds a platform against a wall with a step in front of it,
 * and on a map the size of q2dm1's main hall the planner is allowed up to six
 * of them in one room. What that draws is a heap of crates in the middle of a
 * floor, and the PO has objected to it in every batch he has walked: on
 * 2026-09-10, with a photograph of the main hall, «это не часть архитектуры
 * измененной, это просто мусорница». It is not a construction he wants at any
 * fidelity, and no number of them makes a room more interesting than the room
 * was.
 *
 * NOTHING IS DELETED. The planner below, `block_stands`, `snap_block`,
 * `shape_block` and `build_room_block` are all still here and still correct,
 * and the apply path still builds a block when one is handed to it - which is
 * how `check_mapgen_carving.py` still asks whether an edit leaves a T-junction
 * behind it. What stops is the DEAL: the product schedule offers none, so no
 * fidelity spends its band on crates.
 *
 * What carries the band instead is what the PO named as interesting on the
 * same day: the hollow through a wall, the lift, the flood, the connector
 * that opens. If they do not reach the band, that is a number to report and
 * not a reason to deal crates back.
 */
/*
 * ... and the one way to turn it back on, which no product path uses.
 *
 * `check_mapgen_carving.py` drives the transaction's own gates - the surface
 * fault gate, the leak gate, the playability gate - and the vehicle it drives
 * them with is a room block, because a block is the operator that BUILDS the
 * most brushwork on a bare fixture. Retiring the family from the deal would
 * have left that guard asking its questions of an empty schedule and passing
 * for the wrong reason, which is worse than a red.
 *
 * So the deal is a switch, default off, and `tools/mapgen_transaction_driver`
 * turns it on for `--crates`. That nothing under src/ ever calls the setter is
 * not a promise: `check_mapgen_no_crates.py` reads the tree and asserts it,
 * because a seam is only as good as the call sites it cannot reach (Hard Rule
 * #51 - a seam that proves the algorithm proves nothing about the caller).
 */
static bool g_deal_room_blocks = false;

void MapGenGeometryEdit_DealRoomBlocks(bool on)
{
    g_deal_room_blocks = on;
}

/*
 * Row 405 (W3): walls of courses. Every axial solid box of model zero 8..80 thick on x or y, grouped by that thin
 * extent (to the half unit), joined where two of a group touch or overlap on the other two axes; each group of two or
 * more is one slab, its bounds. Returns how many, the slabs in `*out` (the caller frees).
 */
static uint32_t wall_course_runs(const mapgen_geometry_t *g, float (**out)[6])
{
    *out = NULL;
    const uint32_t nb = MapGenGeometry_NumBrushes(g);
    typedef struct { float lo[3], hi[3]; int thin; uint32_t root; } course_t;
    course_t *c = calloc(nb ? nb : 1, sizeof(*c));
    if (!c)
        return 0;
    uint32_t n = 0;
    for (uint32_t b = 0; b < nb; b++) {
        const mapgen_geometry_brush_t *br = MapGenGeometry_Brush(g, b);
        float lo[3], hi[3];
        if (!br || br->model != 0 || !(br->contents & CONTENTS_SOLID_BIT) || !brush_is_box(g, br, lo, hi))
            continue;
        const float tx = hi[0] - lo[0], ty = hi[1] - lo[1];
        const int thin = tx <= ty ? 0 : 1;
        const float th = thin ? ty : tx;
        if (th < 8.0f || th > 80.0f)
            continue;
        memcpy(c[n].lo, lo, sizeof(lo));
        memcpy(c[n].hi, hi, sizeof(hi));
        c[n].thin = thin;
        c[n].root = n;
        n++;
    }
    /* join: same thin axis and extent, touching on the other two */
    for (uint32_t i = 0; i < n; i++)
        for (uint32_t j = i + 1; j < n; j++) {
            if (c[i].thin != c[j].thin)
                continue;
            const int a = c[i].thin;
            if (fabsf(c[i].lo[a] - c[j].lo[a]) > 0.5f || fabsf(c[i].hi[a] - c[j].hi[a]) > 0.5f)
                continue;
            bool touch = true;
            for (int k = 0; k < 3 && touch; k++)
                if (k != a)
                    touch = c[i].lo[k] <= c[j].hi[k] + 0.5f && c[j].lo[k] <= c[i].hi[k] + 0.5f;
            if (!touch)
                continue;
            uint32_t ri = i, rj = j;
            while (c[ri].root != ri)
                ri = c[ri].root;
            while (c[rj].root != rj)
                rj = c[rj].root;
            if (ri != rj)
                c[rj > ri ? rj : ri].root = rj > ri ? ri : rj;
        }
    float (*runs)[6] = calloc(n ? n : 1, sizeof(*runs));
    uint32_t *members = calloc(n ? n : 1, sizeof(*members));
    uint32_t num = 0;
    if (runs && members) {
        uint32_t *slot = calloc(n ? n : 1, sizeof(*slot));
        if (slot) {
            for (uint32_t i = 0; i < n; i++)
                slot[i] = UINT32_MAX;
            for (uint32_t i = 0; i < n; i++) {
                uint32_t r = i;
                while (c[r].root != r)
                    r = c[r].root;
                if (slot[r] == UINT32_MAX) {
                    slot[r] = num++;
                    for (int a = 0; a < 3; a++) {
                        runs[slot[r]][a] = c[i].lo[a];
                        runs[slot[r]][3 + a] = c[i].hi[a];
                    }
                }
                float *box = runs[slot[r]];
                for (int a = 0; a < 3; a++) {
                    if (c[i].lo[a] < box[a]) box[a] = c[i].lo[a];
                    if (c[i].hi[a] > box[3 + a]) box[3 + a] = c[i].hi[a];
                }
                members[slot[r]]++;
            }
            free(slot);
        }
    }
    /* only the groups of two or more: a single course is the first pass's */
    uint32_t kept = 0;
    for (uint32_t i = 0; runs && members && i < num; i++)
        if (members[i] >= 2u)
            memmove(runs[kept++], runs[i], sizeof(runs[i]));
    free(members);
    free(c);
    /*
     * And a long wall offered by STRETCHES. The window question puts the opening in the middle of what it is given,
     * and a long wall of courses has a middle that backs onto something (q3t2: 152 merged walls asked, 0 glazed):
     * every 64 units a stretch of 128 - room for the 64 opening and a jamb each side - is its own wall. Stretches
     * overlap, and the wall pass takes no second pane where an opening already is.
     */
    uint32_t cap2 = kept * 4u + 16u, num2 = 0;
    float (*parts)[6] = malloc(cap2 * sizeof(*parts));
    for (uint32_t i = 0; parts && runs && i < kept; i++) {
        const float *r = runs[i];
        const int along = (r[3] - r[0]) >= (r[4] - r[1]) ? 0 : 1;
        const float len = r[3 + along] - r[along];
        for (float s = r[along]; ; s += 64.0f) {
            if (num2 == cap2) {
                cap2 *= 2u;
                float (*grown)[6] = realloc(parts, cap2 * sizeof(*parts));
                if (!grown)
                    break;
                parts = grown;
            }
            memcpy(parts[num2], r, sizeof(parts[num2]));
            if (len > 192.0f) {
                parts[num2][along] = s;
                parts[num2][3 + along] = s + 128.0f > r[3 + along] ? r[3 + along] : s + 128.0f;
            }
            num2++;
            if (len <= 192.0f || s + 128.0f >= r[3 + along])
                break;
        }
    }
    free(runs);
    *out = parts;
    return parts ? num2 : 0;
}

